package dev.pocketengine.features.assistant;
import java.util.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public final class OwnerComposerReadingTest {
 private static String id(){return UUID.randomUUID().toString();}
 @Test public void readingAnotherConversationDoesNotSelectItOrChangeActiveDraftAndPending()throws Exception{OwnerComposerState state=OwnerComposerState.empty();var a=state.selectConversation(id());a=state.edit(a.key,a.revision,"A later unsent text🙂","steer",new JSONArray());state.reading(a.key,7,23,"A-anchor","A-tail",false);var pending=state.prepare(id(),a.key,a.revision,"b".repeat(64),null);String active=state.activeKey();long contentRev=state.active().revision;var b=state.readingConversation(id());state.reading(b.key,4,11,"B-anchor","B-tail",false);assertEquals(active,state.activeKey());assertEquals("A later unsent text🙂",state.active().text);assertEquals(contentRev,state.active().revision);assertEquals(7,state.active().scrollIndex);assertEquals(23,state.active().scrollOffset);assertSame(pending,state.pending(pending.clientId));assertEquals(a.key,pending.draftKey);assertNotEquals(active,b.key);}
 @Test public void readingAnchorSurvivesRestartWithoutChangingTheOriginalActiveConversation()throws Exception{OwnerComposerState state=OwnerComposerState.empty();var a=state.selectConversation(id());state.edit(a.key,a.revision,"A pending draft","queue",new JSONArray());String b=id();var reader=state.readingConversation(b);state.reading(reader.key,15,21,"native-message","tail",false);OwnerComposerState restored=OwnerComposerState.fromJson(state.toJson());assertEquals(a.key,restored.activeKey());assertEquals("A pending draft",restored.active().text);var same=restored.readingConversation(b);assertEquals(15,same.scrollIndex);assertEquals(21,same.scrollOffset);assertEquals("native-message",same.anchorMessage);assertEquals(a.key,restored.activeKey());}
 @Test public void aLateAcknowledgementClearsOnlyItsOriginalRevisionNotReadingOrLaterText()throws Exception{OwnerComposerState state=OwnerComposerState.empty();String aId=id(),bId=id();var a=state.selectConversation(aId);a=state.edit(a.key,a.revision,"old sent","queue",new JSONArray());var pending=state.prepare(id(),a.key,a.revision,"c".repeat(64),null);state.edit(a.key,a.revision,"new A draft","queue",new JSONArray());var b=state.readingConversation(bId);state.reading(b.key,8,9,"B-stable","B-tail",false);assertFalse(state.acknowledge(pending.clientId,aId).cleared);assertEquals(a.key,state.activeKey());assertEquals("new A draft",state.active().text);assertEquals("B-stable",state.draft(b.key).anchorMessage);}
}
